class Solution {
public:
    int destroyTargets(vector<int>& nums, int space) {
        unordered_map<int,int> cnt;
        unordered_map<int,int> mn;
        for (int x : nums) {
            int r = x % space;
            cnt[r]++;
            auto it = mn.find(r);
            if (it == mn.end() || x < it->second) mn[r] = x;
        }
        int bestCount = 0, ans = 0;
        for (auto& p : cnt) {
            int r = p.first, c = p.second;
            if (c > bestCount || (c == bestCount && mn[r] < ans)) {
                bestCount = c;
                ans = mn[r];
            }
        }
        return ans;
    }
};
